module design_1_axi_smc_0_lpf
   (lpf_int,
    aclk,
    aresetn);
  output lpf_int;
  input aclk;
  input aresetn;

  wire Q;
  wire aclk;
  wire aresetn;
  wire lpf_asr;
  wire lpf_int;
  wire lpf_int0;
  wire p_0_in;

  design_1_axi_smc_0_cdc_sync \ACTIVE_LOW_AUX.ACT_LO_AUX 
       (.aclk(aclk),
        .aresetn(aresetn),
        .scndry_out(p_0_in));
